from datetime import datetime
from pprint import pformat


class TimeFilter:
    TYPES = {
        'time_filter': ('relative', 'absolute', 'realtime',
                        'today', 'currentMonth', 'previousMonth'),
        'time_from': ('NOW', 'MIDNIGHT'),
        'time_amount': int,
        'time_period': ('MIN', 'HOUR', 'DAY', 'WEEK', 'MONTH'),
        'start_time': datetime,
        'end_time': datetime,
        'look_back_period': int,
    }

    def __init__(self, time_filter, **kwargs):
        """
        Prepare and validate timeFilter scheme compliant to `Time selection` stage
        of `Add To New Board` wizard from `Performance Manage+` application.

        Example of `relative` scheme::

            {
                'type': 'relative',
                'from': 'NOW',
                'amount': 1,
                'period': 'DAY'
            }

        Example of `absolute` scheme::

            {
                'type': 'absolute',
                'start': '2022-02-22T10:00:00+00:00',
                'end': '2022-02-22T11:00:00+00:00'
            }

        Example `realtime` scheme::

            {
                'type': 'realtime',
                'lookBackPeriod': 120
            }

        Example of `today` scheme::

            {
                'type': 'today',
            }

        Example of `currentMonth` scheme::

            {
                'type': 'currentMonth'
            }

        Example of `previousMonth` scheme::

            {
                'type': 'previousMonth'
            }

        :param str time_filter: Allowed types:
            relative, absolute, realtime, today, current_month, previous_month

        :kwargs: Depend on the set ``time_filter`` as follows:

            - time_from (string): Mandatory for ``relative`` time filter.
                Allowed values: ``NOW`` or ``MIDNIGHT``.
            - time_amount (int): Mandatory for ``relative`` time filter.
            - time_period (string): Mandatory for ``relative`` time filter.
                Allowed values: ``MIN``, ``HOUR``, ``DAY``, ``WEEK`` or ``MONTH``.
            - start_time (datetime): Mandatory for ``absolute`` time filter.
            - end_time (datetime): Mandatory for ``absolute`` time filter.
            - look_back_period (int): Mandatory for ``realtime`` time filter (in minutes).
        """

        self.time_filter = self._validate_param('time_filter', time_filter)
        self.kwargs = kwargs
        self.scheme = self._prepare_scheme()

    def _prepare_scheme(self):
        scheme = {'type': self.time_filter}
        if self.time_filter == 'relative':
            scheme['from'] = self._validate_kwarg('time_from')
            scheme['amount'] = self._validate_kwarg('time_amount')
            scheme['period'] = self._validate_kwarg('time_period')
        elif self.time_filter == 'absolute':
            scheme['start'] = self._convert_datetime(
                self._validate_kwarg('start_time'))
            scheme['end'] = self._convert_datetime(
                self._validate_kwarg('end_time'))
        elif self.time_filter == 'realtime':
            scheme['lookBackPeriod'] = self._validate_kwarg('look_back_period')
        return scheme

    def _get_kwarg_value(self, param):
        if param in self.kwargs:
            return self.kwargs[param]
        exc_msg = (f"{param!r} parameter was not provided as a named argument, "
                   f"while it is mandatory for time_filter={self.time_filter!r}")
        raise NameError(exc_msg)

    def _validate_kwarg(self, param):
        value = self._get_kwarg_value(param)
        return self._validate_param(param, value)

    def _validate_param(self, param, value):
        expected_type = self.TYPES[param]
        if isinstance(expected_type, tuple):
            self._validate_value(param, value, expected_type)
        else:
            self._validate_type(param, value, expected_type)
        return value

    @staticmethod
    def _validate_value(param, value, allowed_values):
        if value not in allowed_values:
            exc_msg = (f"{value!r} value is not a valid {param}. "
                       f"Must be one of: {', '.join(allowed_values)}")
            raise ValueError(exc_msg)

    @staticmethod
    def _validate_type(param, value, expected_type):
        if not isinstance(value, expected_type):
            exc_msg = (f"{value!r} value type of {param} parameter is {type(value)}. "
                       f"Expected type: {expected_type}")
            raise TypeError(exc_msg)

    @staticmethod
    def _convert_datetime(date_time):
        """
        Date and time are specified in the ISO 8601 format. The timezone setting is ignored.
        """
        date_time = date_time.replace(microsecond=0).isoformat(sep='T')
        tz = '+00:00'
        return f'{date_time}{tz}'

    def __repr__(self):
        return pformat(self.scheme)
